/* Bad: animates layout properties */
.bad {
  transition: width 0.3s, height 0.3s, top 0.3s;
}
/* Triggers layout + paint + composite every frame */

/* Good: animates compositor-only properties */
.good {
  transition: transform 0.3s ease-out, opacity 0.3s ease-out;
}
/* Only composite → smooth on low-end devices */

.modal-backdrop {
  opacity: 0;
  transition: opacity 0.25s ease-out;
}
.modal-backdrop.open {
  opacity: 1;
}

.tooltip {
  transform: translateY(8px);
  opacity: 0;
  transition: transform 0.2s ease-out, opacity 0.2s ease-out;
}
.tooltip.visible {
  transform: translateY(0);
  opacity: 1;
}

/* Tip: add will-change only when animating */
.animated {
  will-change: transform, opacity;
}

function animateBounce(element, duration = 1000) {
  const start = performance.now();
  const startY = 0;
  const distance = 200;

  function step(now) {
    const elapsed = now - start;
    const progress = Math.min(elapsed / duration, 1);

    // Ease-out cubic for natural feel
    const eased = 1 - Math.pow(1 - progress, 3);

    const currentY = startY + distance * eased;
    element.style.transform = `translateY(${currentY}px)`;

    if (progress < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
}

const box = document.querySelector('.box');
animateBounce(box, 800);

let currentX = 0;
let targetX = 0;
let rafId = null;
const slider = document.querySelector('.slider');

function onPointerMove(e) {
  // Update target from input — very fast
  targetX = e.clientX - 100;

  // Schedule animation frame only if needed
  if (!rafId) {
    rafId = requestAnimationFrame(updateSlider);
  }
}

function updateSlider() {
  rafId = null;

  // Simple lerp toward target
  currentX += (targetX - currentX) * 0.2;

  // Single compositor-only write
  slider.style.transform = `translateX(${currentX}px)`;

  // Continue if not settled
  if (Math.abs(targetX - currentX) > 0.1) {
    rafId = requestAnimationFrame(updateSlider);
  }
}

slider.addEventListener('pointermove', onPointerMove);

